package io.github.jesterportfolio.hearth.survival.platform;

import java.nio.file.*;import java.nio.channels.FileChannel;import java.security.*;import java.util.*;import java.io.*;

/** 후보/원본/저널을 보존하는 명시적 파일 이전. 설정 정본 이외 경로/비밀 설정은 받지 않는다. */
public final class ConfigurationChanges {
    public record Plan(UUID id,String name,String before,String after,boolean restart,Path directory){}
    @FunctionalInterface public interface Validator {void validate(String name,byte[] before,byte[] after)throws Exception;}
    private final Path root,changes;
    public ConfigurationChanges(Path root)throws Exception{this.root=root.toRealPath();changes=this.root.resolve("platform-changes");Files.createDirectories(changes);if(!changes.equals(changes.toRealPath()))throw new IOException("CONFIG_PATH");}
    public static String hash(byte[] data){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));}catch(Exception e){throw new IllegalStateException(e);}}
    private Path file(String name)throws Exception{if(!name.matches("(platform\\.properties|rpg-policy\\.properties|rpg-content\\.properties|enchants/[a-z][a-z0-9_]{0,48}\\.yml)"))throw new IOException("CONFIG_SCOPE");Path file=root.resolve(name);if(!file.equals(file.toRealPath())||!file.getParent().equals(file.getParent().toRealPath())||Files.size(file)>131072||!Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS))throw new IOException("CONFIG_PATH");return file;}
    private byte[] read(Path path)throws Exception{if(!path.equals(path.toRealPath())||!Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS)||Files.size(path)>131072)throw new IOException("CONFIG_PATH");return Files.readAllBytes(path);}
    public Plan stage(String name,String candidate,Validator validator)throws Exception{Path source=file(name);if(!candidate.matches("[a-zA-Z0-9_-]{1,64}\\.candidate"))throw new IOException("CONFIG_CANDIDATE_NAME");byte[] before=read(source),after=read(root.resolve(candidate));validator.validate(name,before,after);if(Arrays.equals(before,after))throw new IOException("CONFIG_UNCHANGED");UUID id=UUID.randomUUID();Path dir=Files.createDirectory(changes.resolve(id.toString()),java.nio.file.attribute.PosixFilePermissions.asFileAttribute(java.nio.file.attribute.PosixFilePermissions.fromString("rwx------")));writeNew(dir.resolve("before"),before);writeNew(dir.resolve("after"),after);var plan=new Plan(id,name,hash(before),hash(after),name.startsWith("rpg-"),dir);var p=new Properties();p.setProperty("version","1");p.setProperty("id",id.toString());p.setProperty("name",name);p.setProperty("before",plan.before);p.setProperty("after",plan.after);p.setProperty("restart",Boolean.toString(plan.restart));p.setProperty("state","STAGED");save(dir.resolve("manifest.properties"),p,false);return plan;}
    public Plan plan(UUID id)throws Exception{Path dir=changes.resolve(id.toString());if(!dir.equals(dir.toRealPath()))throw new IOException("CONFIG_PATH");var p=new Properties();try(var in=new ByteArrayInputStream(read(dir.resolve("manifest.properties")))){p.load(in);}if(!"1".equals(p.getProperty("version"))||!id.toString().equals(p.getProperty("id")))throw new IOException("CONFIG_VERSION");var plan=new Plan(id,p.getProperty("name"),p.getProperty("before"),p.getProperty("after"),Boolean.parseBoolean(p.getProperty("restart")),dir);file(plan.name);if(!plan.before.equals(hash(read(dir.resolve("before"))))||!plan.after.equals(hash(read(dir.resolve("after")))))throw new IOException("CONFIG_EVIDENCE_CHANGED");return plan;}
    public String state(Plan plan)throws Exception{var p=new Properties();try(var in=new ByteArrayInputStream(read(plan.directory.resolve("manifest.properties")))){p.load(in);}return p.getProperty("state");}
    public void mark(Plan plan,String state)throws Exception{if(!Set.of("STAGED","APPLYING","APPLIED","COMMITTED","ROLLING_BACK","ROLLED_BACK").contains(state))throw new IOException("CONFIG_STATE");var p=new Properties();try(var in=new ByteArrayInputStream(read(plan.directory.resolve("manifest.properties")))){p.load(in);}p.setProperty("state",state);save(plan.directory.resolve("manifest.properties"),p,true);}
    public void publish(Plan plan,boolean rollback,Validator validator)throws Exception{Path target=file(plan.name);byte[] actual=read(target),wanted=read(plan.directory.resolve(rollback?"before":"after"));String expected=rollback?plan.after:plan.before,desired=rollback?plan.before:plan.after;if(hash(actual).equals(desired))return;if(!hash(actual).equals(expected))throw new IOException("CONFIG_EXTERNAL_CHANGE");validator.validate(plan.name,actual,wanted);mark(plan,rollback?"ROLLING_BACK":"APPLYING");Path temp=target.resolveSibling(target.getFileName()+".platform-writing");writeNew(temp,wanted);Files.setPosixFilePermissions(temp,Files.getPosixFilePermissions(target));Files.move(temp,target,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);mark(plan,rollback?"ROLLED_BACK":"APPLIED");}
    public List<Plan> pending()throws Exception{var out=new ArrayList<Plan>();try(var paths=Files.list(changes)){var all=paths.toList();if(all.size()>4096)throw new IOException("CONFIG_CAPACITY");for(var path:all){var plan=plan(UUID.fromString(path.getFileName().toString()));if(Set.of("APPLYING","APPLIED","ROLLING_BACK").contains(state(plan)))out.add(plan);}}return List.copyOf(out);}
    private static void writeNew(Path path,byte[] bytes)throws Exception{Files.write(path,bytes,StandardOpenOption.CREATE_NEW);try(var channel=FileChannel.open(path,StandardOpenOption.WRITE)){channel.force(true);}}
    private static void save(Path path,Properties p,boolean replace)throws Exception{var bytes=new ByteArrayOutputStream();p.store(bytes,"Hearth configuration change v1");if(!replace){writeNew(path,bytes.toByteArray());return;}Path temp=path.resolveSibling("manifest.writing");writeNew(temp,bytes.toByteArray());Files.move(temp,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
}
